ALTER TABLE "job_match_history" ADD FOREIGN KEY ("job_posting_id") REFERENCES "job_postings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cover_letter_questions" ADD FOREIGN KEY ("application_id") REFERENCES "applications" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cover_letter_answers" ADD FOREIGN KEY ("question_id") REFERENCES "cover_letter_questions" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

